<?php

namespace App\Http\Requests\Api\V1;

/**
 * Validates POST /baskets: add 1 to 100 baskets at a time, with an optional label.
 * Numbers and tokens are generated by the server, never sent.
 */
class StoreBasketRequest extends BaseApiRequest
{
    public const MAX_BULK = 100;

    protected function attributeMap(): array
    {
        return ['data.attributes.label' => 'label'];
    }

    public function rules(): array
    {
        return [
            // Nothing is required: an empty body adds one basket.
            'data' => 'sometimes|array',
            'data.attributes' => 'sometimes|array',
            'data.attributes.count' => ['sometimes', 'integer', 'min:1', 'max:'.self::MAX_BULK],
            'data.attributes.label' => ['sometimes', 'nullable', 'string', 'max:100'],
        ];
    }

    public function messages(): array
    {
        $message = 'Add between 1 and '.self::MAX_BULK.' baskets at a time.';

        return [
            'data.attributes.count.integer' => $message,
            'data.attributes.count.min' => $message,
            'data.attributes.count.max' => $message,
        ];
    }

    public function count(): int
    {
        return (int) $this->input('data.attributes.count', 1);
    }

    public function bodyParameters(): array
    {
        return [
            'data.attributes.count' => ['description' => 'How many baskets to add (1–100).', 'example' => 10],
            'data.attributes.label' => ['description' => 'A label for all of them.', 'example' => 'Blue, large'],
        ];
    }
}
